-- Investments cell (investments), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA investments;

CREATE FUNCTION investments.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE investments.investments (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    investment_type          text NOT NULL CHECK (investment_type IN ('stock', 'etf', 'fund', 'bond', 'crypto', 'real_estate', 'business', 'other')),
    instrument_key           text CHECK (instrument_key IS NULL OR (length(instrument_key) <= 160)),
    owner_scope              text NOT NULL DEFAULT 'personal' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    account_id               bigint,
    quantity                 double precision CHECK (quantity IS NULL OR (quantity >= 0)),
    cost_basis               double precision CHECK (cost_basis IS NULL OR (cost_basis >= 0)),
    current_value            double precision CHECK (current_value IS NULL OR (current_value >= 0)),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    acquired_on              date,
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('planned', 'active', 'sold', 'closed')),
    metadata                 jsonb CHECK (metadata IS NULL OR (jsonb_typeof(metadata) = 'object')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX investments_legacy ON investments.investments (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX investments_account_id ON investments.investments (workspace_id, account_id);
CREATE INDEX investments_investment_type ON investments.investments (workspace_id, investment_type);
CREATE INDEX investments_owner_scope ON investments.investments (workspace_id, owner_scope);
CREATE INDEX investments_status ON investments.investments (workspace_id, status);

CREATE TABLE investments.market_price_snapshots (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    instrument_key           text NOT NULL CHECK (length(instrument_key) <= 160 AND length(instrument_key) >= 1),
    price                    double precision NOT NULL CHECK (price >= 0),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    as_of                    timestamptz NOT NULL,
    source_type              text NOT NULL CHECK (source_type IN ('exchange', 'broker', 'custodian', 'manual', 'derived')),
    quality                  text NOT NULL DEFAULT 'provisional' CHECK (quality IN ('verified', 'provisional', 'stale', 'rejected')),
    source_ref               text,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, instrument_key, as_of, source_type)
);
CREATE UNIQUE INDEX market_price_snapshots_legacy ON investments.market_price_snapshots (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX market_price_snapshots_instrument_key ON investments.market_price_snapshots (workspace_id, instrument_key);
CREATE INDEX market_price_snapshots_quality ON investments.market_price_snapshots (workspace_id, quality);

CREATE TABLE investments.valuation_snapshots (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    investment_id            bigint NOT NULL,
    market_price_id          bigint,
    quantity                 double precision CHECK (quantity IS NULL OR (quantity >= 0)),
    market_value             double precision CHECK (market_value IS NULL OR (market_value >= 0)),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    valuation_as_of          timestamptz NOT NULL,
    valuation_method         text NOT NULL CHECK (valuation_method IN ('market_price', 'cost_basis', 'manual', 'unpriced')),
    coverage_status          text NOT NULL DEFAULT 'unpriced' CHECK (coverage_status IN ('covered', 'partial', 'unpriced', 'stale', 'invalid')),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, investment_id, valuation_as_of),
    FOREIGN KEY (workspace_id, investment_id) REFERENCES investments.investments (workspace_id, id),
    FOREIGN KEY (workspace_id, market_price_id) REFERENCES investments.market_price_snapshots (workspace_id, id)
);
CREATE UNIQUE INDEX valuation_snapshots_legacy ON investments.valuation_snapshots (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX valuation_snapshots_coverage_status ON investments.valuation_snapshots (workspace_id, coverage_status);
CREATE INDEX valuation_snapshots_investment_id ON investments.valuation_snapshots (workspace_id, investment_id);
CREATE INDEX valuation_snapshots_market_price_id ON investments.valuation_snapshots (workspace_id, market_price_id);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE investments.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('investment', 'market-price', 'valuation')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE investments.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON investments.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['investments', 'market_price_snapshots', 'valuation_snapshots', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE investments.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE investments.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON investments.%I'
                       ' USING (workspace_id = investments.current_workspace())'
                       ' WITH CHECK (workspace_id = investments.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA investments TO investments_api;
GRANT EXECUTE ON FUNCTION investments.current_workspace() TO investments_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON investments.investments, investments.market_price_snapshots, investments.valuation_snapshots TO investments_api;
GRANT USAGE ON SEQUENCE investments.investments_id_seq, investments.market_price_snapshots_id_seq, investments.valuation_snapshots_id_seq TO investments_api;
GRANT SELECT, INSERT ON investments.create_keys TO investments_api;
GRANT SELECT, INSERT ON investments.outbox TO investments_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON investments.outbox TO investments_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON investments.outbox TO investments_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA investments TO investments_publisher;
GRANT SELECT ON investments.outbox TO investments_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON investments.outbox TO investments_publisher;
